+static inline void
+scmi_tlm_to_uapi_des_items(unsigned int num_des,
+			   const struct scmi_telemetry_res_info *in,
+			   struct scmi_tlm_de_info *des)
+{
+	for (int i = 0; i < num_des; i++)
+		scmi_tlm_to_uapi_de_info(&des[i], &in->dei_store[i]);
