+static inline void
+scmi_tlm_to_uapi_grps_list(unsigned int num_groups,
+			   const struct scmi_telemetry_res_info *in,
+			   struct scmi_tlm_grp_info *ginfo)
+{
+	struct scmi_tlm_grp_info *out_ginfo = ginfo;
